{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Weight valid targets by 1+exp2(-d/4), where d is the distance from each sequence's final valid target. This emphasizes recent predictions while retaining prefix supervision across all four datasets.",
      "edits": [
        {
          "find": "    loss = pairwise_loss + 0.2 * pointwise_loss\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    loss = pairwise_loss + 0.2 * pointwise_loss\n    positions = torch.arange(pos.size(1), device=pos.device).unsqueeze(0).expand_as(pos)\n    last_valid = positions.masked_fill(pos.eq(0), -1).max(dim=1, keepdim=True).values\n    distance = (last_valid - positions).clamp(min=0).to(loss.dtype)\n    weights = (1.0 + torch.exp2(-distance / 4.0)) * mask\n    return (loss * weights).sum() / weights.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Change only loss weighting for all four categories. Preserve the existing loss terms, GRU architecture, inference, sampling, optimizer and training settings."
